// @ts-check
// Shared by src/layouts/Base.astro, scripts/og-image.mjs, scripts/icons.mjs,
// and the tests. Paths are relative to the repository root.

/** The only avatar image; every other size and crop is generated from it. */
export const AVATAR_SOURCE = "src/assets/avatar.png";

/**
 * The circle behind the avatar, the same in both themes.
 * Keep in sync with --color-avatar-bg in src/styles/tokens.css.
 */
export const AVATAR_BG = "#ebe5d6";

/**
 * Icons generated by scripts/icons.mjs at build time. `crop` is the square of
 * the 400×400 source to draw: the favicon shows only the head, which stays
 * recognizable at 16–32px. The favicon is a circle; the apple-touch-icon fills
 * the square, because iOS rounds the corners itself and shows transparent
 * pixels as black.
 */
export const ICONS = /** @type {const} */ ({
  favicon: {
    path: "/favicon.png",
    output: "dist/client/favicon.png",
    size: 32,
    shape: "circle",
    crop: { x: 80, y: 0, size: 240 },
  },
  appleTouch: {
    path: "/apple-touch-icon.png",
    output: "dist/client/apple-touch-icon.png",
    size: 180,
    shape: "square",
    crop: { x: 0, y: 0, size: 400 },
  },
});
